/** Contract tests for the thin statistics facade; engine behavior is tested separately. */
class LmdbEvaluationStatisticsMemoizationTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI FIRST = VF.createIRI("urn:first");
	private static final IRI SECOND = VF.createIRI("urn:second");

	@Test
	void facadePreservesExactAlgebraLeafContracts() {
		LmdbEvaluationStatistics statistics = statistics();
		BindingSetAssignment values = values(1, 1, 2);

		assertEquals(0.0d, statistics.getCardinality(new EmptySet()));
		assertEquals(1.0d, statistics.getCardinality(new SingletonSet()));
		assertEquals(3.0d, statistics.getCardinality(values));
		assertFalse(statistics.supportsJoinEstimation());
	}

	@Test
	void rdfStatisticsBoundaryUsesTheCanonicalEnginePath() {
		LmdbEvaluationStatistics statistics = statistics();
		StatementPattern first = pattern("s", FIRST, "x");
		StatementPattern second = pattern("x", SECOND, "y");
		Join joined = new Join(first.clone(), second.clone());

		StatisticsEstimate firstEstimate = statistics.statementPattern(first, Set.of()).orElseThrow();
		StatisticsEstimate joinEstimate = statistics.multiPatternJoin(List.of(first, second), Set.of()).orElseThrow();

		assertEquals(statistics.getCardinality(first), firstEstimate.rows());
		assertEquals(statistics.getCardinality(joined), joinEstimate.rows());
		assertTrue(firstEstimate.bag().variables().containsKey("s"));
		assertTrue(joinEstimate.bag().variables().keySet().containsAll(Set.of("s", "x", "y")));
	}

	@Test
	void physicalCostingDoesNotRewriteSemanticRows() {
		LmdbEvaluationStatistics statistics = statistics();
		StatementPattern pattern = pattern("s", FIRST, "x");
		CostContext repeated = CostContext.of(Set.of("s"), 12.0d, 4.0d, true);

		var cost = statistics.estimateFactorCost(pattern, repeated).orElseThrow();

		assertEquals(statistics.getCardinality(pattern), cost.getOutputRows());
		assertEquals(12.0d, cost.getDoubleMetrics().get("plannedRepeatedInvocations"),
				"Distinct lookup bindings do not reduce nested-loop RHS executions without a cache contract");
		assertTrue(cost.getWorkRows() >= cost.getOutputRows());
	}

	@Test
	void emptyOuterPrefixAnnihilatesOtherwisePositiveBoundLookupCost() {
		LmdbEvaluationStatistics statistics = statistics();
		StatementPattern pattern = pattern("s", FIRST, "x");
		assertTrue(statistics.getCardinality(pattern) > 0.0d,
				"The lookup must be positive without an outer-prefix constraint");

		var cost = statistics.estimateFactorCost(pattern,
				CostContext.of(Set.of("s"), 0.0d, 7.0d, true)).orElseThrow();

		assertEquals(0.0d, cost.getOutputRows(), 0.0d);
		assertEquals(0.0d, cost.getWorkRows(), 0.0d);
		assertEquals(0.0d, cost.getDoubleMetrics().get("plannedRowsPerInvocation"), 0.0d);
		assertEquals(0.0d, cost.getDoubleMetrics().get("plannedRepeatedInvocations"), 0.0d);
		assertEquals(0.0d, cost.getDoubleMetrics().get("plannedSeeks"), 0.0d);
	}

	@Test
	void finiteValuesFactorCostRetainsDisjointOuterInvocationMass() {
		LmdbEvaluationStatistics statistics = statistics();
		BindingSetAssignment codes = values(200, 201, 202);
		CostContext repeated = CostContext.of(Set.of("entity"), 66_500.0d, Double.NaN, true);

		var cost = statistics.estimateFactorCost(codes, repeated).orElseThrow();

		assertEquals(199_500.0d, cost.getOutputRows(), 0.0d);
		assertEquals(199_500.0d, cost.getWorkRows(), 0.0d,
				"Three VALUES rows must be charged exactly once for every outer entity");
		assertEquals(66_500.0d, cost.getDoubleMetrics().get("plannedRepeatedInvocations"), 0.0d);
		assertTrue(cost.isRepeatedInvocationsCosted());
	}

	@Test
	void filterEstimateScalesWithSelectedMemoInput() {
		LmdbEvaluationStatistics statistics = statistics();
		StatementPattern input = pattern("s", FIRST, "x");
		ValueConstant trueCondition = new ValueConstant(VF.createLiteral(true));

		StatisticsEstimate tenRows = selectedInputEstimate(10.0d);
		StatisticsEstimate hundredRows = selectedInputEstimate(100.0d);
		StatisticsEstimate tenFiltered = statistics.filter(input, trueCondition, tenRows, Set.of()).orElseThrow();
		StatisticsEstimate hundredFiltered = statistics.filter(input, trueCondition, hundredRows, Set.of())
				.orElseThrow();

		assertEquals(tenFiltered.rows() * 10.0d, hundredFiltered.rows(), 0.0d,
				"Filter costing must retain the selected memo input's row scale");
		assertEquals(tenFiltered.bag().variable("s").boundRows() * 10.0d,
				hundredFiltered.bag().variable("s").boundRows(), 0.0d,
				"Filter costing must retain proportional selected-input binding evidence");
	}

	@Test
	void optimizationScopeOwnsAndReleasesRuntimeCaches() {
		LmdbEvaluationStatistics statistics = statistics();
		assertFalse(statistics.estimatorRuntime().hasPlannerCache());

		try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
			assertTrue(statistics.estimatorRuntime().hasPlannerCache());
			assertEquals(statistics.estimatorRuntime().planTemplateCache(),
					statistics.estimatorRuntime().planTemplateCache());
		}

		assertFalse(statistics.estimatorRuntime().hasPlannerCache());
	}

	@Test
	void optimizationScopeReusesStructurallyEquivalentFactorCosts() {
		LmdbEvaluationStatistics statistics = statistics();
		StatementPattern pattern = pattern("s", FIRST, "x");
		CostContext context = CostContext.of(Set.of("s"), 12.0d, 4.0d, true);

		try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
			var first = statistics.estimateFactorCost(pattern, context).orElseThrow();
			var equivalentClone = statistics.estimateFactorCost(pattern.clone(), context).orElseThrow();

			assertSame(first, equivalentClone,
					"One optimization must estimate each structural factor and complete cost context only once");
		}
	}

	@Test
	void optimizationScopeMemoizesAndBoundsExactAlternativeScans(@TempDir File dataDir) {
		IRI firstLeft = VF.createIRI("urn:alternative:first:left");
		IRI firstRight = VF.createIRI("urn:alternative:first:right");
		IRI secondLeft = VF.createIRI("urn:alternative:second:left");
		IRI secondRight = VF.createIRI("urn:alternative:second:right");
		int rowsPerPredicate = 1_050;
		LmdbStore store = new LmdbStore(dataDir, new LmdbStoreConfig("spoc,ospc,psoc,posc"));
		SailRepository repository = new SailRepository(store);
		repository.init();

		try {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				List<IRI> predicates = List.of(firstLeft, firstRight, secondLeft, secondRight);
				for (int predicateOrdinal = 0; predicateOrdinal < predicates.size(); predicateOrdinal++) {
					for (int row = 0; row < rowsPerPredicate; row++) {
						connection.add(VF.createIRI("urn:alternative:subject:" + predicateOrdinal + ':' + row),
								predicates.get(predicateOrdinal), VF.createLiteral(row));
					}
				}
				connection.commit();
			}

			LmdbEvaluationStatistics statistics = (LmdbEvaluationStatistics) store.getBackingStore()
					.getEvaluationStatistics();
			LmdbEstimatorRuntime runtime = statistics.estimatorRuntime();
			TupleExpr firstAlternative = new Union(
					pattern("subject", firstLeft, "leftObject"),
					pattern("subject", firstRight, "rightObject"));
			TupleExpr secondAlternative = new Union(
					pattern("subject", secondLeft, "object"),
					pattern("subject", secondRight, "object"));

			try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
				var first = runtime.exactAlternativeSurface(firstAlternative);
				assertTrue(first.isPresent());
				assertSame(first, runtime.exactAlternativeSurface(firstAlternative.clone()),
						"Equivalent relations must reuse one exact scan result inside an optimization");
				assertEquals(rowsPerPredicate * 2.0d, first.orElseThrow().surfaceRows(), 0.0d);
				var relation = first.orElseThrow().relation();
				assertNotNull(relation,
						"An exact heterogeneous alternative must retain its tuples for downstream Frontier state");
				assertEquals(Set.of("subject", "leftObject", "rightObject"), Set.copyOf(relation.variables()));
				assertEquals(rowsPerPredicate * 2.0d, relation.rows(), 0.0d);
				int leftSlot = relation.variables().indexOf("leftObject");
				int rightSlot = relation.variables().indexOf("rightObject");
				assertEquals(rowsPerPredicate,
						relation.frequencies()
								.entrySet()
								.stream()
								.filter(entry -> entry.getKey().get(leftSlot) != null)
								.mapToDouble(java.util.Map.Entry::getValue)
								.sum(),
						0.0d);
				assertEquals(rowsPerPredicate,
						relation.frequencies()
								.entrySet()
								.stream()
								.filter(entry -> entry.getKey().get(rightSlot) != null)
								.mapToDouble(java.util.Map.Entry::getValue)
								.sum(),
						0.0d);
				assertTrue(runtime.exactAlternativeSurface(secondAlternative).isEmpty(),
						"Distinct exact scans must share one bounded query-local scan budget");
			}

			try (QueryOptimizationScope ignored = statistics.beginQueryOptimizationScope()) {
				assertEquals(rowsPerPredicate * 2.0d,
						runtime.exactAlternativeSurface(secondAlternative).orElseThrow().surfaceRows(), 0.0d,
						"A new optimization scope must receive a fresh exact-scan budget");
			}
		} finally {
			repository.shutDown();
		}
	}

	private static LmdbEvaluationStatistics statistics() {
		return new LmdbEvaluationStatistics(null, null, null, null, null, null);
	}

	private static StatementPattern pattern(String subject, IRI predicate, String object) {
		return new StatementPattern(new Var(subject), new Var("predicate", predicate), new Var(object));
	}

	private static StatisticsEstimate selectedInputEstimate(double rows) {
		BagEstimate bag = BagEstimate.exact(rows, "selected-memo-input")
				.withVariable("s", VariableEstimate.bound(rows, rows))
				.withVariable("x", VariableEstimate.bound(rows, rows));
		return StatisticsEstimate.fromBag(bag, "selected-memo-input");
	}

	private static BindingSetAssignment values(int... values) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		List<BindingSet> rows = java.util.Arrays.stream(values).mapToObj(value -> {
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("x", VF.createLiteral(value));
			return (BindingSet) bindings;
		}).toList();
		assignment.setBindingSets(rows);
		return assignment;
	}
}
